<?php
require_once __DIR__.'/../config/database.php';require_once __DIR__.'/../includes/auth.php';require_sales_access();$page_title='Follow-ups';$current_page='followups';$user=current_user();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();if(!can_manage_sales()){http_response_code(403);exit('Read-only access.');}$action=$_POST['action']??'';if($action==='add'){$leadId=(int)$_POST['lead_id'];$date=$_POST['follow_up_date']??'';$time=$_POST['follow_up_time']?:null;$type=trim($_POST['type']??'Call');$notes=trim($_POST['notes']??'');$assigned=(int)($_POST['assigned_to']??0)?:null;if($user['role']==='staff'){$assigned=$user['id'];}if($leadId<1||!$date){flash('error','Lead and follow-up date are required.');}else{$lead=assert_lead_access($pdo,$leadId);$s=$pdo->prepare('INSERT INTO lead_followups(lead_id,assigned_to,follow_up_date,follow_up_time,type,notes,status,created_by) VALUES(?,?,?,?,?,?,?,?)');$s->execute([$leadId,$assigned,$date,$time,$type,$notes,'Pending',$user['id']]);$pdo->prepare('UPDATE leads SET follow_up_date=? WHERE id=?')->execute([$date,$leadId]);log_activity($pdo,$leadId,$user['id'],'Follow-up','Follow-up scheduled for '.format_day($date).'.');flash('success','Follow-up added.');redirect('followups.php?lead_id='.$leadId);}}elseif($action==='complete'){$id=(int)$_POST['id'];$s=$pdo->prepare("UPDATE lead_followups SET status='Completed',completed_at=NOW() WHERE id=?");$s->execute([$id]);$x=$pdo->prepare('SELECT lead_id FROM lead_followups WHERE id=?');$x->execute([$id]);$leadId=(int)$x->fetchColumn();if($leadId){assert_lead_access($pdo,$leadId);}log_activity($pdo,$leadId,$user['id'],'Follow-up','Follow-up marked completed.');flash('success','Follow-up completed.');redirect('followups.php');}}
$leadId=(int)($_GET['lead_id']??0);$params=[];$vis=lead_visibility_sql($params,'l');$q=$pdo->prepare("SELECT l.id,l.name,l.company FROM leads l WHERE 1=1$vis ORDER BY l.created_at DESC");$q->execute($params);$leads=$q->fetchAll();$users=$user['role']==='staff'?[['id'=>$user['id'],'username'=>$user['username']]]:$pdo->query("SELECT id,username FROM users WHERE role IN ('admin','b2b_manager','staff') ORDER BY username")->fetchAll();$params=[];$vis=lead_visibility_sql($params,'l');$q=$pdo->prepare("SELECT f.*,l.name,l.company,u.username assignee FROM lead_followups f JOIN leads l ON l.id=f.lead_id LEFT JOIN users u ON u.id=f.assigned_to WHERE 1=1$vis ORDER BY f.follow_up_date ASC, f.follow_up_time ASC, f.id DESC LIMIT 100");$q->execute($params);$rows=$q->fetchAll();require __DIR__.'/../includes/header.php';
?><div class="detail-grid"><div class="section-card"><div class="section-head"><h2>Follow-up List</h2></div><div class="table-wrap"><table class="table"><thead><tr><th>Date</th><th>Lead</th><th>Type</th><th>Assigned</th><th>Status</th><th></th></tr></thead><tbody><?php if(!$rows):?><tr><td colspan="6" class="empty">No follow-ups yet.</td></tr><?php else:foreach($rows as $r):?><tr><td><?=e(format_day($r['follow_up_date']))?><?php if($r['follow_up_time']):?><div class="muted"><?=e(date('h:i A',strtotime($r['follow_up_time'])))?></div><?php endif;?></td><td><a href="lead.php?id=<?=$r['lead_id']?>"><strong><?=e($r['company']?:$r['name'])?></strong></a></td><td><?=e($r['type'])?></td><td><?=e($r['assignee']?:'Unassigned')?></td><td><span class="badge <?=$r['status']==='Completed'?'badge-green':'badge-orange'?>"><?=e($r['status'])?></span></td><td><?php if($user['role']!=='qc' && $r['status']!=='Completed'):?><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="complete"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="btn btn-light btn-sm">Complete</button></form><?php endif;?></td></tr><?php endforeach;endif;?></tbody></table></div></div>
<?php if($user['role']!=='qc'): ?><div class="section-card form-card"><h2 style="margin-top:0">Add Follow-up</h2><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="add"><div class="field"><label>Lead</label><select class="form-control" name="lead_id" required><?php foreach($leads as $l):?><option value="<?=$l['id']?>" <?=$leadId===$l['id']?'selected':''?>><?=e($l['company']?:$l['name'])?></option><?php endforeach;?></select></div><div class="form-grid" style="margin-top:18px"><div class="field"><label>Date</label><input class="form-control" type="date" name="follow_up_date" required></div><div class="field"><label>Time</label><input class="form-control" type="time" name="follow_up_time"></div></div><div class="field" style="margin-top:18px"><label>Type</label><select class="form-control" name="type"><option>Call</option><option>Email</option><option>WhatsApp</option><option>Other</option></select></div><div class="field" style="margin-top:18px"><label>Assigned To</label><select class="form-control" name="assigned_to"><option value="">Unassigned</option><?php foreach($users as $u):?><option value="<?=$u['id']?>"><?=e($u['username'])?></option><?php endforeach;?></select></div><div class="field" style="margin-top:18px"><label>Notes</label><textarea class="form-control textarea" name="notes"></textarea></div><div class="form-actions"><button class="btn btn-primary">Save Follow-up</button></div></form></div></div><?php endif; ?><?php require __DIR__.'/../includes/footer.php'; ?>
